import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"CRONOS: Benchmarking Counterfactual Physical Consistency in Video Models","description":"","frontmatter":{"title":"CRONOS: Benchmarking Counterfactual Physical Consistency in Video Models","arxiv":"2605.23699","date":"2026-05-22","authors":"León Begiristain, Olaf Dünkel, Adam Kortylewski","categories":"cs.CV","topics":"物理感知视频生成, 反事实一致性, 评测基准","outline":[2,2]},"headers":[],"relativePath":"papers/2605.23699.md","filePath":"papers/2605.23699.md","lastUpdated":null}'),l={name:"papers/2605.23699.md"};function e(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="cronos-benchmarking-counterfactual-physical-consistency-in-video-models" tabindex="-1">CRONOS: Benchmarking Counterfactual Physical Consistency in Video Models <a class="header-anchor" href="#cronos-benchmarking-counterfactual-physical-consistency-in-video-models" aria-label="Permalink to &quot;CRONOS: Benchmarking Counterfactual Physical Consistency in Video Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.23699" target="_blank" rel="noreferrer">2605.23699</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-22</td></tr><tr><td><strong>作者</strong></td><td>León Begiristain, Olaf Dünkel, Adam Kortylewski</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>在 Unreal Engine 里把同一个物理事件按视角/场景/物体类别/外观做全因子干预渲染，用对象级指标量化「同一事件在不同观测下生成质量的波动」，把物理评测从「单条视频对不对」推进到「换个看法还对不对」。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型被当作世界模型来用，前提是它学到的是场景动力学，而不是「这类画面下一帧长什么样」的视觉统计。这两者在单条视频上几乎无法区分：一个只会复述训练集里常见碰撞画面的模型，和一个真的表征了刚体接触的模型，在同一个提示下可能给出同样漂亮的结果。</p><p>CRONOS 把这个区分变成可测量的量。它提出<strong>反事实物理一致性</strong>（counterfactual physical consistency）：固定底层物理事件（碰撞、下落、遮挡），只改变一个视觉因子（相机视角、场景、物体类别、物体外观），看模型的生成质量如何随之波动。对视角和外观这类不改变物理参数的干预，好的模型输出质量应当稳定；对物体类别和场景这类会改变质量、摩擦、几何的干预，应当协调地改变。质量的剧烈波动说明模型把预测编码成了强视角依赖、强外观依赖的东西。</p><p>为什么重要：把视频模型接进规划或策略训练时，你无法控制相机架在哪、桌上放的是马克杯还是易拉罐。如果换个机位模型的物理就崩了，任何基于 rollout 的下游用途都不可靠——而现有 benchmark 报的平均分完全看不出这一点。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>物理评测这条线已经相当密集。PISA 比较自由落体的物体轨迹；Physics-IQ 用真实物理实验录像做图像级比较；Morpheus 直接检查运动方程是否被满足；WorldBench 从生成视频里估计物理参数并与仿真对照；VideoPhy / PhyGenBench / WorldSimBench 用人工或 VLM 判物理常识。合成环境这一侧，CLEVRER、IntPhys、Physion、CRAFT 都提供了受控场景。</p><p>它们的共同结构是：<strong>给定一个固定的视觉观测，评价这条生成对不对</strong>。这能告诉你模型在某个具体场景上失败了，但推不出失败是因为「不懂碰撞」还是「这个机位没见过」。作者点名的另一个缺口是渲染质量：多数合成物理 benchmark 用的是简单纹理、平光照的基本几何体，与真实视频分布差距过大，模型在上面的表现不一定迁移。CRONOS 用 Unreal Engine 的商业 3D 资产在 1920×1080/30FPS 下渲染，同时保留仿真器的完全可控性——这是它相对 CLEVRER/Physion 那一支的主要差异。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2026 年之前已经存在两条独立的经验：一是鲁棒性评测领域早就用「受控扰动 + 性能下降幅度」作为表征是否结构化的探针（ImageNet-C 那一系）；二是 kang2024howfar 在简化 2D 环境里发现，视频生成器可以在分布内预测上随规模变好，却学不到能外推的物理律。</p><p>把两者接起来的想法并不复杂：物理评测缺的不是更多场景，而是<strong>匹配的场景对</strong>。真实视频无法提供这种配对——你没法保证两条真实录像除了机位以外一切相同。仿真器可以，但过去的仿真 benchmark 把仿真用在「造简单题目」上，而不是「造受控对照组」。于是路径就清楚了：用高保真渲染器做全因子设计，每次只动一个因子，把「质量在这一维上的最大-最小差」当作敏感度指标。度量这一侧同样要重做，因为 FVD 这类分布级指标在单条视频上没有意义，需要能把外观、几何、运动分开的对象级指标。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>同一个物理事件从两个机位看，动力学完全没变；一个真正表征了 3D 动力学的模型应该给出同样质量的两条 rollout。所以不必去问「这条视频物理对不对」这个难题，只需要问「换个看法之后质量掉了多少」。质量的波动本身就是诊断信号，且不需要任何物理真值——它只需要配对。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「碰撞」事件为例走一遍：</p><ul><li><strong>事件定义</strong>：在 Unreal 里给一个物体施加初始冲量，让它滑过桌面撞上另一个物体。质量、摩擦、恢复系数按物体显式设定并在所有事件间保持一致。</li><li><strong>干预渲染</strong>：固定这套物理配置，分别替换背景场景（5 种）、被撞物体类别（5 种，同时改变质量与形状）、外观颜色（3 种）、相机机位（4 种）。三类事件（fall / collision / occlusion）做全因子组合，遮挡事件不改视角以保住可见性结构，总计 675 条参考视频。仿真器同时输出逐物体分割掩码。</li><li><strong>生成</strong>：每个模型在 I2V（首帧）和 V2V（5 帧条件）设定下按同一提示模板生成，每个配置采 3 个种子取 best-of-three（按运动相似度选）。评测的模型是 Cosmos2.5-2B/14B、CogVideoX1.5-5B、MAGI-1-4.5B、Wan2.2-14B。</li><li><strong>打分</strong>：对生成视频跑 SAM3 分割 + CoTracker3 跟踪，再算五个指标——外观稳定性（DINOv2 CLS 余弦相似度）、背景稳定性（共享背景像素 MSE）、3D 形状稳定性（SAM3D 重建网格的 Chamfer 距离）、运动相似度（DisMo 外观无关运动编码器）、物理合理性（Qwen3-VL-32B 按事件特定的 5+5 道二元问题判定）。所有指标用「最差 5% 帧的平均」而非全帧平均聚合，因为少数崩坏帧对人的感知影响远大于平均值。</li><li><strong>成功率与敏感度</strong>：阈值由 540 条视频的人工评分标定（令假阳性率与假阴性率相等），五项全部过阈才算成功；敏感度定义为同一干预轴内最好与最差配置的差，跨组跨指标平均。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>指标本身是几个简单的鲁棒聚合。外观稳定性取跨帧跨物体的稳健最小值：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">ObjectStability</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.7279em;vertical-align:-0.8638em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-2.3723em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop"><span class="mord mathrm">RobustMin</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8638em;"><span></span></span></span></span></span><span class="mspace"> </span><span class="mopen">⟨</span><span class="mord"><span class="mord mathrm">CLS</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8436em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">CLS</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)⟩</span></span></span></span></span></p><p>背景与形状用稳健最大值（误差越大越差），再用指数压缩到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">exp</span><span class="mopen">(</span><span class="mord">−</span><span class="mord">50</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span></span></span></span>。这个指数映射值得注意——它对小误差极其敏感，MSE 从 0.01 到 0.02 会让分数从 0.61 掉到 0.37，所以背景稳定性这一列的绝对数值不适合按线性理解。</p><p>物理合理性用了倒数缩放而非线性平均：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">PhysicalPlausibility</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord"><span class="delimsizing size2">(</span></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3521em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">1</span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">VLM</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.004em;vertical-align:-0.65em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Ideal</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mord"><span class="mord"><span class="delimsizing size2">)</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:1.354em;"><span style="top:-3.6029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span></span></p><p>直觉是「答错一题就掉到 1/2，答错两题掉到 1/3」，让单个明确的物理违反无法被其他正确回答稀释。这与整套评测的设计哲学一致：物理失败是灾难性的，不该被平均掉。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：模型能不能生成基本刚体物理？</strong> 表 1 给出的答案是几乎不能。最强的两个配置 Cosmos2.5-2B (V2V) 和 Wan2.2-14B (I2V) 的成功率分别是 0.22 和 0.20，其余在 0.01–0.14 之间；MAGI-1-4.5B 在 V2V 下只有 0.01。人类研究里运动合理性与事件质量的中位评分普遍在 1.3–1.9（5 分制），与自动指标一致。</p><p><strong>问题二：质量在干预下稳不稳？</strong> 不稳。作者的结论是外观干预最被容忍（约 0.14–0.28 的敏感度），而视角干预波动最大。这里需要如实指出：<strong>附录表 8 的逐指标敏感度并不支持「视角波动最大」这个说法</strong>。在 15 个模型-事件组合里，视角只在 4 个（主要是 MAGI-1）是最大项，场景与物体类别在多数格子里更高，例如 Cosmos2.5-14B 在 Fall/V2V 上是场景 0.45 &gt; 物体 0.37 &gt; 视角 0.35。图 5 是跨事件聚合后的结果，正文的措辞比表格支持的更强。可以确定的结论是较弱的那一版：<strong>所有模型在所有干预轴上都有 0.14–0.5 量级的质量波动，连纯改颜色都能带来约 20% 的变化</strong>。</p><p><strong>问题三：视频条件比图像条件强吗？</strong> 强，且不只强在运动上。V2V 相对 I2V 不仅运动相似度更高（这符合预期，多给的 5 帧带有速度方向信息），背景稳定性和对象稳定性也更好。作者的解释是条件片段里没有相机运动，为生成提供了比纯文本更强的「镜头不动」信号——这是推测，论文没有做消融。</p><p><strong>问题四：放大模型有用吗？</strong> 在这个家族里没用。Cosmos2.5 从 2B 到 14B，几乎每个指标都变差，V2V 成功率从 0.22 掉到 0.14。作者谨慎地把它限定为单一模型族的单次尺度跨越，但与 kang2024howfar 的 2D 结论方向一致。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：CRONOS 用 Unreal Engine 做全因子干预渲染，把物理评测从「这条视频对不对」改成「同一事件换个观测后质量掉多少」。它给出五个对象级指标（外观/背景/3D 形状/运动/VLM 物理），阈值由 540 条视频的人评标定，五项全过才算成功。五个开源模型在 675 条基础事件上的成功率最高只有 22%，多数低于 15%。所有模型对四类干预都表现出大幅质量波动，连只改颜色都有约 20% 的变化。Cosmos2.5 从 2B 放到 14B 反而全面变差，说明规模本身不带来反事实一致性。</p><p><strong>3 句话版</strong>：物理评测缺的不是更难的场景，而是只差一个因子的配对场景。CRONOS 用高保真仿真器造出这种配对，发现当前开源视频模型既生成不好基本刚体物理（成功率 ≤22%），也无法在干预下保持稳定。规模在这个维度上不是解药。</p><p><strong>1 句话版</strong>：把「同一物理事件的不同观测」造成受控对照组之后，现有视频模型的物理能力显示出强烈的视觉相关性依赖，而非结构化的动力学表征。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>生成质量指标的波动可以被解读为物理表征的不稳定</strong>。这条链子中间有一个薄弱环节——所有指标本身都依赖 SAM3/SAM3D/DisMo/Qwen3-VL 这几个感知模型，而这些模型自身对视角同样敏感。俯视机位下的分割质量、单目 3D 重建的形状估计、运动编码器的嵌入，都会随机位系统性变化。换句话说，观测到的「视角敏感度」里有多少来自生成器、有多少来自评测器，论文没有分离。</p><p>论文提供的证据是 540 条视频的人工研究，显示指标与人评正相关。但这个研究验证的是「指标能排序质量」，不是「指标在不同视角下具有同等标定」——后者才是敏感度分析真正需要的。一个直接的补救是把真值渲染本身送进整条评测管线，测出评测器在无生成误差情况下的跨视角波动作为噪声底。论文没有报这个数。附录里确实提到用首帧的真值掩码去 prompt SAM3 并传播，这缓解了初始化偏差，但不解决传播过程的视角依赖。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做且不需要复现完整基准：</p><ul><li>取 CRONOS 发布的 675 条参考视频（不生成任何东西），对<strong>真值渲染本身</strong>跑完整评测管线。</li><li>测量：把真值视频当作「生成结果」与自身参考对比，逐指标记录分数与跨视角敏感度。</li><li>支持论文的结果：真值在所有视角上分数接近满分，敏感度接近 0，说明评测器本身是视角中立的，观测到的敏感度归因于生成器。</li><li>反驳论文的结果：真值的跨视角敏感度已经达到生成结果敏感度的相当比例（比如 0.1 以上），说明「视角是最敏感干预」这个结论部分来自感知模型而非生成模型。</li><li>成本：只需跑一遍分割、3D 重建、运动编码与 VLM 判定，无需 H100 生成时间。作者报的评测成本是每个配置 60 A100 小时。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者最有力的攻击是<strong>多解性</strong>。I2V 设定下，一张首帧加一段粗略提示远不足以确定未来：碰撞后两个物体飞向哪里、物体在桌沿以多快速度离开，都有一整族物理上都合法的答案。论文用「参考视频只有一条」的运动相似度作为主要运动指标，并用 3 个种子取最优来缓解。但 best-of-3 只是把多解性的方差往下压了一点，并没有改变度量目标仍是「像不像那一条特定 rollout」。</p><p>由此产生一个替代解释：<strong>观测到的敏感度可能主要反映不同干预下多解空间的宽窄，而非表征稳定性</strong>。换个机位会改变哪些物理量在画面里可辨识（比如侧视能看清水平速度，俯视看不清），于是模型在不同视角下面对的实际是难度不同的推断任务，质量差异是任务难度差异而不是表征不稳。</p><p>设计一个能区分两者的实验：对每个干预配置渲染 K 条物理上都合法的参考 rollout（改变初始冲量的微小扰动），把运动相似度改成对这个集合取最大值。如果敏感度在集合式评测下大幅塌缩，说明原结论主要是多解性伪影；如果基本不变，说明确实是表征问题。论文在 Limitations 里承认了这一点并把集合式评测列为未来工作，但没有给出任何该方向的证据。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：CRONOS 诊断出「视角依赖」，但诊断是黑箱的——它只知道换机位质量掉了，不知道模型内部哪一层把预测锚死在了 2D 图像统计上。作为一个纯评测工作，它给出的改进目标（「让模型跨条件一致」）无法直接转成训练信号。</p><p><strong>新 framing</strong>：把反事实一致性从<strong>评测指标</strong>变成<strong>训练目标</strong>，用仿真器提供的配对结构做等变性正则。相邻领域可借的工具是自监督表征学习里的等变对比学习（equivariant SSL）与多视图一致性正则：给定同一物理事件的两个机位 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与已知的相对位姿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">12</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，要求扩散骨干的中间表征满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord">Φ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:-0.1389em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">12</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span class="mclose">))</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Φ</span></span></span></span> 是一个学习到的、由位姿参数化的算子。与现有的几何注入方法（Geometry Forcing 那一支把表征对齐到 3D 重建特征）不同，这里不需要显式 3D 表征，只需要配对与相对变换——这正是 CRONOS 的数据生成管线免费提供的东西。</p><p><strong>第一个实验</strong>：在 CRONOS 的 fall 事件上，用 4 个机位构造配对，在 CogVideoX-2B 上加这个等变项微调 2k 步；主指标不是绝对分数，而是<strong>视角敏感度</strong>。判定标准明确：视角敏感度显著下降且外观/场景敏感度不恶化，说明等变约束确实注入了视角无关的动力学表征；若视角敏感度下降但绝对成功率同步下降，说明模型只是学会了在所有机位上一致地变差，这个 failure mode 必须被显式排除。</p>',48)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
